      "caption": {
        "type": "string",
        "description": "主金额的辅助说明",
        "sampleValue": "本月水电待缴"
      },
      "periodText": {
        "type": "string",
        "description": "当前账单所属账期",
        "sampleValue": "6月账单"
      },
      "dueDateText": {
        "type": "string",
        "description": "建议完成缴费的截止时间",
        "sampleValue": "7月12日前"
      },
      "reminderText": {
        "type": "string",
        "description": "欠费后的短提醒文案",
        "sampleValue": "逾期可能停供"
      },
      "updatedText": {
        "type": "string",
        "description": "账单数据最近更新时间",
        "sampleValue": "10:24更新"
      }
    }
  },
  "assetCandidates": []
}

